const common = `
CONTEXT: Audiobookshelf (ghcr.io/advplyr/audiobookshelf:2.36.0) runs on docker-host. Library root on the host is /mnt/audiobooks (mounted in-container as /data/audiobooks). Layout is Author/Book Title/files. Access via: ssh -o BatchMode=yes mm@docker-host '<cmd>'. Roughly 47 author folders, 1028 files (625 mp3, 153 m4b, 114 jpg, 109 json, 24 cue, 3 nfo).

AUTHORITY: STRICTLY READ-ONLY. Do not rename, move, delete, or edit anything on docker-host, and do not touch the container or its DB. Use ls/find/stat/head/file/ffprobe (if present)/exiftool (if present) only. Do not print binary. Work in the local repo cwd only for writing your report.

WHAT COUNTS AS A PROBLEM (Audiobookshelf's folder-based import rules): author folder spelling variants/duplicates; book folders that don't follow 'Title' or 'Series - Vol N - Title' / 'Vol N - Title' conventions so series/sequence won't be parsed; boxed sets or omnibus folders duplicating individual books; folders holding multiple books at once (mixed titles in one folder); a book split across multiple folders; loose audio files directly in an author folder (no book folder); stray/junk files (.nfo, .cue with no matching audio, .txt, .url, thumbs, empty dirs, zero-byte files); mixed mp3+m4b in one book folder; chapter files with inconsistent zero-padding or ordering that will sort wrong (e.g. 1,10,2); missing or multiple cover images; metadata.json / .opf that disagree with folder names; obvious typos; narrator or year stuffed into titles inconsistently; file/folder names with trailing spaces, odd unicode, or Windows-forbidden chars.

METHOD: List every book folder in your range, then for each: file count, extension mix, presence of cover + metadata.json, and a quick look at the file-name pattern (head -5 sorted). Read metadata.json for title/series/authors where present and compare to folder names. Sample ffprobe/exiftool tags on one file per folder only if the tool exists; don't spend long on tags.

OUTPUT: Write a Markdown report to the path given below with: (1) a table of every book folder in your range with a one-word verdict (ok / rename / merge / dedupe / junk / investigate), (2) a prioritised list of concrete issues, each with the exact current path(s) and the proposed fix (proposed new name, delete, merge target, etc.), (3) anything you couldn't determine. Be terse; no preamble. Reply in chat with a 5-line summary and the report path.

STOP if ssh fails or the path is missing; report that instead of guessing.`;

const lanes = [
  { key: 'scout-a-e', label: 'Scout authors A–E', range: "author folders whose name starts with A, B, C, D or E (i.e. A.F. Steadman through Eoin Colfer inclusive). Use: ls /mnt/audiobooks | grep -E '^[A-E]'", report: 'tmp/abs-audit/scout-a-e.md' },
  { key: 'scout-f-j', label: 'Scout authors F–J', range: "author folders whose name starts with F, G, H, I or J (this includes the three Tolkien variants 'J. R. R. Tolkien', 'J.R.R. Tolkein', 'J.R.R. Tolkien' — diff their contents carefully and propose a single canonical folder). Use: ls /mnt/audiobooks | grep -E '^[F-J]'", report: 'tmp/abs-audit/scout-f-j.md' },
  { key: 'scout-k-z', label: 'Scout authors K–Z', range: "author folders whose name starts with K through Z. Use: ls /mnt/audiobooks | grep -E '^[K-Z]'", report: 'tmp/abs-audit/scout-k-z.md' },
];

const fsRuns = lanes.map(l => runs.run({
  key: l.key,
  label: l.label,
  agent: 'scout',
  model: 'sonnet',
  task: `OBJECTIVE: Audit the audiobook library folders in your assigned range and report what needs cleaning up for Audiobookshelf import.\n\nYOUR RANGE: ${l.range}\n\nREPORT PATH (local, create dir if needed): ${l.report}\n${common}`,
}));

const dbRun = runs.run({
  key: 'scout-abs-db',
  label: 'Scout Audiobookshelf DB view',
  agent: 'scout',
  model: 'sonnet',
  task: `OBJECTIVE: Report how Audiobookshelf itself has imported the library — items it flagged as missing/invalid, unmatched titles, duplicate authors, empty series, items with no cover, and items whose parsed title/author/series disagrees with folder names.\n\nACCESS: ssh -o BatchMode=yes mm@docker-host. The container is named 'audiobookshelf'; its DB is the docker volume audiobookshelf-data mounted at /config/absdatabase.sqlite. sqlite3 is NOT in the container. READ-ONLY approach: copy the DB out (e.g. docker cp audiobookshelf:/config/absdatabase.sqlite /tmp/abs-audit.sqlite on docker-host, or 'docker run --rm -v audiobookshelf-data:/c:ro alpine cat /c/absdatabase.sqlite > /tmp/abs-audit.sqlite'), then query the COPY with whatever is available on docker-host (sqlite3, or python3 -c with the sqlite3 module). Never open the live DB file. Delete /tmp/abs-audit.sqlite when done. Also check the last ~300 lines of the ABS logs in the container (/config/logs) for scan warnings about the library.\n\nUSEFUL TABLES (ABS 2.x): libraryItems (path, relPath, isMissing, isInvalid, mediaType), books (title, subtitle, publishedYear, coverPath, narrators, asin, isbn), authors (name), bookAuthors, series (name), bookSeries (sequence), podcasts (ignore). Look for: isMissing/isInvalid=1; authors with near-duplicate names (case/spacing/typo variants); books with null coverPath; series with one member or inconsistent sequences; books whose title differs from the last path segment; libraryItems whose relPath has trailing spaces or odd characters.\n\nAUTHORITY: STRICTLY READ-ONLY on docker-host apart from the temp DB copy in /tmp, which you must remove. Do not restart, scan, or modify the container.\n\nOUTPUT: Write a Markdown report to tmp/abs-audit/scout-abs-db.md in the local cwd (create dir if needed): a summary table of counts, then a prioritised list of concrete findings with item paths and proposed fixes. Terse, no preamble. Reply in chat with a 5-line summary and the report path. STOP and report if ssh fails, the DB can't be copied, or no sqlite client exists on the host.`,
});

const results = await runs.all([...fsRuns, dbRun]);
return results;

